    it.each<[EventType, string]>([
      ['all', '1 inbound event · usually 0–4 a week'],
      ['call_received', '1 call · usually 0–4 a week'],
      ['lead_created', '1 lead · usually 0–4 a week'],
      ['appointment_set', '1 appointment · usually 0–4 a week'],
