import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { Router, provideRouter } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { ActivityHealthReport } from '../app/core/models';
import { FakeActivityHealthApi } from './fake-apis';
import { chooseOption, getButton, getSelect, selectedOptionText, locationRows, cellTexts, columnHeaderTexts } from './dom-queries';
import { currentQueryParams, recordNavigations, settle } from './router-testing';

@Component({
  selector: 'app-probe',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<label for="acct">Viewing as</label><select id="acct" (change)="pick($any($event.target).value)"><option value="14" [selected]="true">Beacon</option><option value="6">Metro</option></select>
  <label>Activity type <select><option>All activity</option></select></label>
  <button type="button" disabled>◀ Previous week</button>
  <p>{{ report()?.summary?.count }}</p>
  <table><thead><tr><th>Location</th><th>Events</th></tr></thead><tbody>@for (l of report()?.locations ?? []; track l.location) {<tr><th scope="row">{{l.location}}</th><td>{{l.count}}</td></tr>}</tbody></table>`,
})
class Probe {
  private readonly router = inject(Router);
  readonly report = signal<ActivityHealthReport | undefined>(undefined);
  constructor() {
    new FakeActivityHealthApi().getActivityHealth({ accountId: 14, week: null, eventType: 'all' }).subscribe((r) => {
      this.report.set(r);
      void this.router.navigate([], { queryParams: { account: 14, week: r.latestCompleteWeek, type: 'all' }, queryParamsHandling: 'merge', replaceUrl: true });
    });
  }
  pick(value: string): void { void this.router.navigate([], { queryParams: { account: value }, queryParamsHandling: 'merge' }); }
}

describe('harness probe', () => {
  it('works', async () => {
    TestBed.configureTestingModule({ providers: [provideRouter([{ path: 'dashboard', component: Probe }])] });
    const navs = recordNavigations(TestBed.inject(Router));
    const harness = await RouterTestingHarness.create();
    await harness.navigateByUrl('/dashboard?ref=x');
    await settle(harness);
    const root = harness.fixture.nativeElement as HTMLElement;
    expect(currentQueryParams()).toEqual({ ref: 'x', account: '14', week: '2026-07-20', type: 'all' });
    expect(navs.at(-1)?.replaceUrl).toBe(true);
    expect(root.textContent).toContain('26');
    expect(locationRows(root).map((r) => cellTexts(r)[0])).toEqual(['Site B', 'Site C', 'Site A', 'Site D']);
    expect(columnHeaderTexts(root)).toEqual(['Location', 'Events']);
    expect(selectedOptionText(getSelect(root, 'Viewing as'))).toBe('Beacon');
    expect(getSelect(root, 'Activity type')).toBeTruthy();
    expect(getButton(root, '◀ Previous week').disabled).toBe(true);
    chooseOption(getSelect(root, 'Viewing as'), 'Metro');
    await settle(harness);
    expect(currentQueryParams()['account']).toBe('6');
    expect(navs.at(-1)?.replaceUrl).toBe(false);
  });
});
EOF
